tool_and_message_events.command:
/bin/bash -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile, writeFile } from 'node:fs/promises';
import { readMinor, mulDivMinor } from './work/lib/money.mjs';

const input = JSON.parse(await readFile('work/rows.json', 'utf8'));
const settlement = input.map(({ id, unitMinor, quantity }) => {
  assert(Number.isSafeInteger(quantity));
  const net = mulDivMinor(readMinor(unitMinor), BigInt(quantity), 1n, 'floor');
  return {
    id,
    net: { unit: 'EUR-cent', value: net.toString() },
    fee: {
      status: 'blocked',
      requiredDecision: 'Марина, владелец расчётов, должна утвердить применимость сбора. Если сбор применяется, нужно утвердить числитель и знаменатель ставки, а также правило округления. Основание: R-35.'
    }
  };
});

const expected = [['BR', 153n], ['BS', -30n]];
const json = JSON.stringify(settlement, null, 2) + '\\n';
const verify = (rows) => {
  assert.deepEqual(rows.map(({ id, net }) => {
    assert.deepEqual(Object.keys(net).sort(), ['unit', 'value']);
    assert.equal(net.unit, 'EUR-cent');
    return [id, readMinor(net.value)];
  }), expected);
  for (const { fee } of rows) {
    assert.equal(fee.status, 'blocked');
    assert.deepEqual(Object.keys(fee).sort(), ['requiredDecision', 'status']);
    assert(fee.requiredDecision.includes('R-35'));
  }
};
verify(JSON.parse(json));
await writeFile('settlement.json', json);
verify(JSON.parse(await readFile('settlement.json', 'utf8')));
console.log('Проверены две строки, DTO net и состояние сбора.');
NODE"

